import type { IncomingMessage, ServerResponse } from "node:http";
export default async function handler(request: IncomingMessage, response: ServerResponse) {
  try {
    const [{ createRequestListener }, { app }] = await Promise.all([
      import("remix/node-fetch-server"),
      // @ts-expect-error Generated by the Vite server build, before Vercel traces the function.
      import("../dist/server/app.js"),
    ]);
    await new Promise<void>((resolve, reject) => {
      response.once("finish", resolve);
      response.once("close", resolve);
      response.once("error", reject);
      createRequestListener(app, { trustProxy: true })(request, response);
    });
  } catch (error) {
    const cause = error as { code?: string; name?: string; message?: string };
    const code = cause.code ?? cause.name ?? "UNKNOWN";
    const match = cause.message?.match(/Cannot find (?:package|module) ['"]([^'"]+)['"]/);
    const missing = match?.[1] ?? cause.message?.match(/require\(\) of ES Module ([^\s]+)/)?.[1];
    const diagnostic = /^[A-Z_a-z]+$/.test(code) ? code : "UNKNOWN";
    response.statusCode = 500;
    response.setHeader("Content-Type", "text/plain; charset=utf-8");
    response.end(
      "Server runtime could not start: " +
        diagnostic +
        (missing && /^[@A-Za-z0-9_./-]+$/.test(missing) ? " (" + missing + ")" : ""),
    );
  }
}
